gN1(){return"\u041d\u0430\u0440\u0430\u0437\u0456 \u0423\u043d\u0446\u0456\u0430\u043b 0229 \u0437\u0431\u0435\u0440\u0456\u0433\u0430\u0454\u0442\u044c\u0441\u044f \u0432 \u041f\u0430\u043f\u0456\u0440\u043e\u043b\u043e\u0433\u0456\u0447\u043d\u043e\u043c\u0443 \u0456\u043d\u0441\u0442\u0438\u0442\u0443\u0442\u0456 \u0414\u0436\u0456\u0440\u043e\u043b\u0430\u043c\u043e \u0412\u0456\u0442\u0435\u043b\u043b\u0456 \u0443 \u0424\u043b\u043e\u0440\u0435\u043d\u0446\u0456\u0457, \u0406\u0442\u0430\u043b\u0456\u044f."},
